    int32_t nParticleXY;
    int nParticleOffset;
    D2GfxInfoUnkStrc* pGfxInfoUnk;
    BOOL BVar1;
    D2UnitStrc* pOwnerUnit;
    D2InventoryStrc* pInventoryUsed;
