    uint8_t* pCofIdentity;
    uint32_t nLayerIdx;
    D2GfxDataStrc sGfxData;
    int nFrameMetricY;
    int nFrameResult;
    int nFrameCount;
    int32_t nTransformGfx;
    int32_t nHealthBarColor;
    int nMaxSpriteHeight;
    uint32_t nFrame;
    int nClassId;
    uint8_t* pCofLayerData;
    uint8_t* pCofIdentityBase;
